-- Canonical Silver is the only mart source; CREATE OR REPLACE makes reruns non-additive.
CREATE OR REPLACE TABLE `${catalog}`.`${schema}`.gold_daily_sales AS SELECT date(invoice_timestamp) sales_date,sum(gross_merchandise_sales) gross_sales,sum(cancellation_value) cancellation_exposure,sum(net_merchandise_value) net_value FROM `${catalog}`.`${schema}`.silver_transactions GROUP BY 1;
CREATE OR REPLACE TABLE `${catalog}`.`${schema}`.gold_monthly_sales AS SELECT date_trunc('MONTH',invoice_timestamp) month_start,date_trunc('MONTH',invoice_timestamp)=max(date_trunc('MONTH',invoice_timestamp)) over() is_partial_month,count(distinct date(invoice_timestamp)) observed_dates,sum(gross_merchandise_sales) gross_sales,sum(cancellation_value) cancellation_exposure,sum(net_merchandise_value) net_value FROM `${catalog}`.`${schema}`.silver_transactions GROUP BY 1;
CREATE OR REPLACE TABLE `${catalog}`.`${schema}`.gold_product_performance AS SELECT stock_code,max(description) description,sum(gross_merchandise_sales) gross_sales,sum(cancellation_value) cancellation_exposure,sum(net_merchandise_value) net_value FROM `${catalog}`.`${schema}`.silver_transactions WHERE item_type='MERCHANDISE' GROUP BY 1;
CREATE OR REPLACE TABLE `${catalog}`.`${schema}`.gold_country_performance AS SELECT country,sum(gross_merchandise_sales) gross_sales,sum(cancellation_value) cancellation_exposure,sum(net_merchandise_value) net_value FROM `${catalog}`.`${schema}`.silver_transactions WHERE item_type='MERCHANDISE' GROUP BY 1;
CREATE OR REPLACE TABLE `${catalog}`.`${schema}`.gold_customer_rfm AS WITH p AS (SELECT customer_id,max(invoice_timestamp) last_purchase,count(distinct invoice_no) purchase_frequency,sum(gross_merchandise_sales) monetary FROM `${catalog}`.`${schema}`.silver_transactions WHERE customer_id is not null AND item_type='MERCHANDISE' AND line_class='SALE' GROUP BY 1) SELECT *,datediff((SELECT max(invoice_timestamp) FROM `${catalog}`.`${schema}`.silver_transactions),last_purchase) recency_days,CASE WHEN monetary>=2000 AND purchase_frequency>=5 THEN 'CHAMPION' WHEN purchase_frequency>=3 THEN 'LOYAL' ELSE 'DEVELOPING' END segment FROM p;
CREATE OR REPLACE TABLE `${catalog}`.`${schema}`.gold_cohort_retention AS WITH a AS (SELECT customer_id,date_trunc('MONTH',invoice_timestamp) activity_month,min(date_trunc('MONTH',invoice_timestamp)) over(partition by customer_id) cohort_month FROM `${catalog}`.`${schema}`.silver_transactions WHERE customer_id is not null AND item_type='MERCHANDISE' AND line_class='SALE'), d AS (SELECT DISTINCT customer_id,cohort_month,activity_month FROM a), z AS (SELECT cohort_month,activity_month,count(*) retained_customers FROM d GROUP BY cohort_month,activity_month) SELECT cohort_month,activity_month,retained_customers,months_between(activity_month,cohort_month) month_number,retained_customers/first_value(retained_customers) over(partition by cohort_month order by activity_month) retention_rate FROM z;
CREATE OR REPLACE TABLE `${catalog}`.`${schema}`.gold_cancellation_exposure AS SELECT stock_code,count(*) cancellation_lines,sum(cancellation_value) cancellation_value FROM `${catalog}`.`${schema}`.silver_transactions WHERE line_class='CANCELLATION' AND item_type='MERCHANDISE' GROUP BY stock_code;
CREATE OR REPLACE TABLE `${catalog}`.`${schema}`.gold_data_quality_metrics AS SELECT run_id,metric,value,measured_at FROM `${catalog}`.`${schema}`.dq_metrics WHERE metric IN ('source_rows','accepted_rows','quarantine_rows','rescued_rows','duplicate_source_identity','unknown_review_rows','source_max_epoch_seconds');
